[CmdletBinding()]
param(
    [Parameter()]
    [string]$Repositorio = 'C:\xampp\htdocs\guinchafacil'
)

$ErrorActionPreference = 'Stop'
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
$timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backups = @()
$created = @()

$conteudos = [ordered]@{
    'src\Views\public\parceiros\index.php' = ''
    'src\Views\public\parceiros\guinchos.php' = ''
    'src\Views\public\parceiros\oficinas.php' = ''
    'src\Views\public\checkout-veiculo.php' = ''
    'src\Views\pagamento\checkout.php' = ''
}

function Restore-Changes {
    Write-Host '[A3][ROLLBACK] Restaurando arquivos...' -ForegroundColor Yellow

    foreach ($item in $backups) {
        Copy-Item -LiteralPath $item.Backup -Destination $item.Path -Force
        Write-Host ('[A3][ROLLBACK] Restaurado: {0}' -f $item.Path)
    }

    foreach ($path in $created) {
        if (Test-Path -LiteralPath $path) {
            Remove-Item -LiteralPath $path -Force
            Write-Host ('[A3][ROLLBACK] Removido: {0}' -f $path)
        }
    }
}

try {
    if (-not (Test-Path -LiteralPath $Repositorio -PathType Container)) {
        throw ('[A3][CONFIG] Repositorio nao encontrado: {0}' -f $Repositorio)
    }

    $php = 'C:\xampp\php\php.exe'
    if (-not (Test-Path -LiteralPath $php -PathType Leaf)) {
        throw ('[A3][CONFIG] PHP do XAMPP nao encontrado: {0}' -f $php)
    }

    $footerComponent = Join-Path $Repositorio 'src\Views\components\gf-footer-payments.php'
    $footerCss = Join-Path $Repositorio 'public\assets\css\components\gf-footer-payments.css'
    if (-not (Test-Path -LiteralPath $footerComponent -PathType Leaf)) {
        throw '[A3][PRECONDITION] Componente gf-footer-payments.php da Onda 2 nao encontrado.'
    }
    if (-not (Test-Path -LiteralPath $footerCss -PathType Leaf)) {
        throw '[A3][PRECONDITION] CSS gf-footer-payments.css da Onda 2 nao encontrado.'
    }

    foreach ($relativePath in $conteudos.Keys) {
        $path = Join-Path $Repositorio $relativePath
        $directory = Split-Path -Parent $path
        [System.IO.Directory]::CreateDirectory($directory) | Out-Null

        if (Test-Path -LiteralPath $path -PathType Leaf) {
            $backup = '{0}.bak-{1}' -f $path, $timestamp
            Copy-Item -LiteralPath $path -Destination $backup -Force
            $backups += [pscustomobject]@{ Path = $path; Backup = $backup }
            Write-Host ('[A3][BACKUP] {0}' -f $backup)
        }
        else {
            $created += $path
        }

        $bytes = [System.Convert]::FromBase64String($conteudos[$relativePath])
        $content = $utf8NoBom.GetString($bytes)
        [System.IO.File]::WriteAllText($path, $content, $utf8NoBom)
        Write-Host ('[A3][WRITE] {0}' -f $relativePath)
    }

    foreach ($relativePath in $conteudos.Keys) {
        $path = Join-Path $Repositorio $relativePath
        $lintOutput = & $php -l $path 2>&1
        if ($LASTEXITCODE -ne 0) {
            throw ('[A3][LINT] Falhou em {0}: {1}' -f $relativePath, ($lintOutput -join ' '))
        }
        Write-Host ('[A3][LINT] OK: {0}' -f $relativePath)
    }

    Write-Host '[A3][DONE] Parceiros e checkout visual instalados com sucesso.' -ForegroundColor Green
    exit 0
}
catch {
    Write-Host ('[A3][ERROR] {0}' -f $_.Exception.Message) -ForegroundColor Red
    Restore-Changes
    exit 1
}

